mapper.select:
SELECT COUNT(*) > 0
  FROM guardias_servicios_medicos sm
 WHERE sm.IdServicio = #{servicioId}
   AND sm.IdMedico = #{medicoId}

SELECT m.ID AS id, m.Nombre AS nombre, m.Apellidos AS apellidos, sm.ActivoServicio AS activoServicio
  FROM guardias_servicios_medicos sm
  JOIN medicos m ON m.ID = sm.IdMedico
 WHERE sm.IdServicio = #{servicioId}
 AND sm.IdMedico = #{medicoId}
 ORDER BY m.Apellidos, m.Nombre, m.ID

SELECT v.IdMedico AS medicoId, v.FDay AS fecha, g.Id AS guardiaId, g.Festivo AS guardiaFestivo,
       g.Tipo AS guardiaTipo, g.IdServicio AS guardiaServicioId
  FROM vacaciones_medicos v
  JOIN guardias_servicios_medicos sm ON sm.IdMedico = v.IdMedico AND sm.IdServicio = #{servicioId}
  LEFT JOIN guardias_medicos g
    ON g.IdMedico = v.IdMedico AND LEFT(g.FGuardia, 10) = v.FDay AND g.IdServicio = #{servicioId}
 WHERE v.FDay BETWEEN #{desde} AND #{hasta}
 AND v.IdMedico = #{medicoId}
 ORDER BY v.IdMedico, v.FDay
